    'Access to this criminal intelligence system is strictly limited to verified police personnel. All login attempts, sessions, and case investigations are monitored and auditable under law.': 'இந்த குற்ற நுண்ணறிவு அமைப்புக்கான அணுகல் சரிபார்க்கப்பட்ட காவல்துறை அதிகாரிகளுக்கு மட்டுமே கண்டிப்பாக வரையறுக்கப்பட்டுள்ளது. அனைத்து உள்நுழைவு முயற்சிகள், அமர்வுகள் மற்றும் வழக்கு விசாரணைகள் சட்டத்தின் கீழ் கண்காணிக்கப்படுகின்றன.',
