    'Tracks movements without optical surveillance coverage and suggests targeted intelligence collection actions.': 'ഒപ്റ്റിക്കൽ നിരീക്ഷണ കവറേജ് ഇല്ലാത്ത ചലനങ്ങൾ ട്രാക്ക് ചെയ്യുകയും ലക്ഷ്യമിട്ടുള്ള രഹസ്യാന്വേഷണ ശേഖരണ പ്രവർത്തനങ്ങൾ നിർദ്ദേശിക്കുകയും ചെയ്യുന്നു.',
